// W1 - Step 1: Validate Incident
const raw = $input.first().json;
const payload = raw.body || raw;
const incident = payload.incident || {};

if (!incident.id && !incident.code) {
  incident.id = 'inc-' + Date.now();
}
incident.code = incident.code || incident.id || 'INC-2026';
incident.severity = incident.severity || 'CRITICAL';

return [{
  json: {
    ...payload,
    incident,
    responsePlan: payload.responsePlan || {},
    resources: payload.resources || { ambulances: [], rescueTeams: [], drones: [] },
    action: payload.action || 'TRIGGER_FULL_ORCHESTRATION',
    simulationMode: payload.simulationMode !== undefined ? payload.simulationMode : true,
    validatedAt: new Date().toISOString(),
    validationPassed: true
  }
}];

// W1 - Step 2: Create / Update Incident Context
const data = $input.first().json;
const inc = data.incident;

const incidentContext = {
  incidentId: inc.id,
  code: inc.code,
  title: inc.title || 'Unclassified Event',
  severity: inc.severity || 'CRITICAL',
  status: inc.status || 'ACTIVE',
  primaryLocation: inc.primaryLocation?.name || inc.location || 'Sector Alpha',
  waterLevel: inc.metrics?.waterLevelMeters || 2.4,
  affectedPopulation: inc.metrics?.affectedPopulationEstimated || 1200,
  updatedAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    incidentContext
  }
}];

// W1 - Step 3: Analyze Severity
const data = $input.first().json;
const sev = (data.incidentContext.severity || 'MEDIUM').toUpperCase();
const isCritical = sev === 'CRITICAL' || sev === 'CATASTROPHIC' || sev === 'HIGH';

return [{
  json: {
    ...data,
    severityAnalysis: {
      severity: sev,
      isCritical,
      requiresHumanApproval: isCritical,
      escalationLevel: isCritical ? 'DEFCON_2_SEVERE' : 'DEFCON_4_NORMAL'
    }
  }
}];

// W2 - Step 2: Allocate Resources
const data = $input.first().json;
const req = data.responsePlan?.resourceAllocation || { ambulances: 2, rescueTeams: 2, drones: 1 };

const allocatedResources = {
  incidentId: data.incident.id,
  ambulancesAllocated: req.ambulances || 2,
  rescueTeamsAllocated: req.rescueTeams || 2,
  dronesAllocated: req.drones || 1,
  priorityZone: data.incident.primaryLocation?.name || 'Zone A',
  allocationApprovedAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    allocatedResources,
    isApproved: true
  }
}];

// W2 - Step 3: Trigger Mock Ambulance Workflow
const data = $input.first().json;

const ambulanceDispatch = {
  service: 'AMBULANCE_108_CAD',
  unitsMobilized: data.allocatedResources.ambulancesAllocated,
  destination: data.allocatedResources.priorityZone,
  status: 'SIMULATED_DISPATCH',
  dispatchTimestamp: new Date().toISOString(),
  disclaimer: 'Mock Dispatch: Prototype demonstration. No real vehicles mobilized.'
};

return [{
  json: {
    ...data,
    ambulanceDispatch
  }
}];

// W2 - Step 4: Trigger Mock Rescue Team Workflow
const data = $input.first().json;

const rescueTeamDispatch = {
  service: 'SDRF_WATER_RESCUE',
  teamsMobilized: data.allocatedResources.rescueTeamsAllocated,
  boatSquads: 2,
  destination: data.allocatedResources.priorityZone,
  status: 'SIMULATED_DEPLOYMENT',
  dispatchTimestamp: new Date().toISOString(),
  disclaimer: 'Mock Dispatch: Prototype demonstration.'
};

return [{
  json: {
    ...data,
    rescueTeamDispatch
  }
}];

// W3 - Step 1: Check Available Drones
const data = $input.first().json;
const drones = data.resources?.drones || [
  { id: 'drone-101', callsign: 'UAV Echo-1', flightStatus: 'STANDBY_PAD', batteryPercentage: 94 },
  { id: 'drone-102', callsign: 'UAV Talon-2', flightStatus: 'STANDBY_PAD', batteryPercentage: 88 }
];

const availableDrones = drones.filter(d => (d.batteryPercentage || 90) > 30);

return [{
  json: {
    ...data,
    droneInventory: {
      totalUnits: drones.length,
      availableUnits: availableDrones
    }
  }
}];

// W3 - Step 2: Select Available Drone
const data = $input.first().json;
const available = data.droneInventory?.availableUnits || [];

const selectedDrone = available[0] || {
  id: 'drone-101',
  callsign: 'UAV Echo-1',
  model: 'Matrice 300 RTK',
  batteryPercentage: 94
};

return [{
  json: {
    ...data,
    selectedDrone
  }
}];

// W3 - Step 3: Create Mission
const data = $input.first().json;
const targetZone = data.incident?.primaryLocation?.name || 'Zone A';

const mission = {
  missionId: `MSN-${Date.now().toString(36).toUpperCase()}`,
  droneCallsign: data.selectedDrone?.callsign || 'UAV Echo-1',
  targetZone,
  flightPattern: 'PERIMETER_THERMAL_GRID',
  altitudeMeters: 45,
  payload: 'FLIR Thermal Recon + Floatation Vest Drop',
  createdAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    droneMission: mission
  }
}];

// W3 - Step 4: Update Mission Status
const data = $input.first().json;
const isDeploy = data.action === 'DEPLOY_DRONE' || data.isApproved;

const finalDroneStatus = isDeploy ? 'IN_FLIGHT' : 'READY';

const updatedMission = {
  ...data.droneMission,
  flightStatus: finalDroneStatus,
  groundSpeedKmH: isDeploy ? 38.5 : 0,
  telemetryActive: isDeploy
};

return [{
  json: {
    ...data,
    droneMission: updatedMission,
    droneWorkflowStatus: finalDroneStatus
  }
}];

// W4 - Step 1: Generate Emergency Alert
const data = $input.first().json;
const target = data.incident?.primaryLocation?.name || 'Zone A';

const alertDraft = {
  alertId: `CAP-${data.incident?.code || 'ALERT'}`,
  headline: `URGENT FLOOD ADVISORY: Evacuate ${target}`,
  urgency: 'Immediate',
  instruction: 'Move to elevated ground via Highland Arterial R4 immediately.',
  protocol: 'COMMON_ALERTING_PROTOCOL_V1.2',
  draftedAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    alertDraft
  }
}];

// W4 - Step 3: Publish / Simulate Alert
const data = $input.first().json;

const publishedBroadcast = {
  ...data.alertDraft,
  status: 'SIMULATED',
  disseminationChannel: 'SIMULATED_CELL_BROADCAST_EAS',
  broadcastTimestamp: new Date().toISOString(),
  disclaimer: 'Mock Broadcast: Simulated emergency siren stubs.'
};

return [{
  json: {
    ...data,
    publishedBroadcast,
    emergencyAlertStatus: 'SIMULATED'
  }
}];

// W4 - Step 4: Log Alert & Consolidate Final State
const data = $input.first().json;

const alertStatus = data.emergencyAlertStatus || 'PENDING APPROVAL';
const criticalStatus = data.isApproved ? 'APPROVED' : 'WAITING FOR APPROVAL';
const droneStatus = data.droneWorkflowStatus || 'READY';

const logs = [
  {
    id: 'log-1-intake',
    timestamp: new Date().toISOString(),
    workflow: 'Incident Intake',
    status: 'SUCCESS',
    message: `[Workflow 1 Intake] Validated ${data.incident.code} (${data.incidentContext.severity}). Branched to Critical Response.`
  },
  {
    id: 'log-2-critical',
    timestamp: new Date().toISOString(),
    workflow: 'Critical Response',
    status: data.isApproved ? 'SUCCESS' : 'PENDING',
    message: data.isApproved
      ? `[Workflow 2 Critical] Commander clearance confirmed. Mobilized ${data.allocatedResources?.ambulancesAllocated || 2} ambulances & ${data.allocatedResources?.rescueTeamsAllocated || 2} boat teams.`
      : '[Workflow 2 Critical] Human approval safeguard active. Awaiting EOC Commander signature.'
  },
  {
    id: 'log-3-drone',
    timestamp: new Date().toISOString(),
    workflow: 'Drone Deployment',
    status: 'SUCCESS',
    message: `[Workflow 3 Drone] ${data.selectedDrone?.callsign || 'UAV Echo-1'} flight status: ${droneStatus} (Alt: 45m).`
  },
  {
    id: 'log-4-alert',
    timestamp: new Date().toISOString(),
    workflow: 'Emergency Alert',
    status: alertStatus === 'SIMULATED' ? 'MOCK' : 'PENDING',
    message: `[Workflow 4 Alert] CAP Broadcast Status: ${alertStatus}.`
  }
];

const finalResponse = {
  success: true,
  orchestrator: 'RUNNING',
  incidentIntake: 'COMPLETED',
  criticalResponse: criticalStatus,
  droneWorkflow: droneStatus,
  emergencyAlert: alertStatus,
  allocated: data.allocatedResources || null,
  droneMission: data.droneMission || null,
  alertPayload: data.publishedBroadcast || data.alertDraft || null,
  logs,
  disclaimer: 'PROTOTYPE DEMONSTRATION: External real emergency services are not connected. Dispatch actions are simulated via mock stubs.'
};

return [{ json: finalResponse }];
